 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate full-length separator lines, then copy the first patterned tile
    # into every tile position while preserving separators.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    if not sep_rows or not sep_cols:
        return [row[:] for row in grid]
    sr, sc = sep_rows[0], sep_cols[0]
    # Source is first tile above/left of the separators.
    tile = [row[:sc] for row in grid[:sr]]
    out = [row[:] for row in grid]
    for r0 in range(0, h, sr + 1):
        for c0 in range(0, w, sc + 1):
            if r0 == 0 and c0 == 0:
                continue
            for r in range(sr):
                for c in range(sc):
                    if r0 + r < h and c0 + c < w:
                        out[r0 + r][c0 + c] = tile[r][c]
    return out
